"""Intent Router — 意图识别与路由。

参考 agentd/core/intent_router.py。分层策略（确定性优先）：
1. 规则匹配（关键词+正则）→ 零 Token
2. 缓存查询（MD5 键，7 天有效）→ 零 Token
3. LLM 分类（~50 tokens）→ 结果回写缓存
"""
import hashlib
import json
import logging
import re
import time
from pathlib import Path

logger = logging.getLogger("agent.router")

# 缓存有效期（秒）
CACHE_TTL = 7 * 86400

# ─────────────────────────────────────────────
# 内置默认规则（可被 Skill manifest 规则补充）
# ─────────────────────────────────────────────
DEFAULT_RULES = [
    {
        'intent': 'query_knowledge',
        'keywords': ['什么是', '怎么', '如何', '为什么', '解释', '说明', '介绍'],
        'context_keywords': [],
        'regex': None,
        'skill': None,  # 不走 Skill，直接 LLM 回答
        'confidence': 0.60,
    },
    {
        'intent': 'query_time',
        'keywords': ['几点了', '什么时间', '现在时间', '日期', '星期几',
                     '今天几号', '什么时候', 'deadline', '截止'],
        'context_keywords': [],
        'regex': None,
        'skill': None,
        'confidence': 0.90,
        'shortcut': True,  # 标记为快捷路径，直接本地处理
    },
]


class IntentRouter:
    """分层意图识别：规则 → 缓存 → LLM。"""

    def __init__(self, config, llm_client=None, skill_manager=None):
        self.config = config
        self.llm = llm_client
        self.cache_file = Path(config.intent_cache_file)
        self.cache_file.parent.mkdir(parents=True, exist_ok=True)
        self.rules = list(DEFAULT_RULES)
        self._cache = self._load_cache()
        if skill_manager:
            self.rules.extend(skill_manager.get_intent_rules())

    # ─────────────────────────────────────────
    # 缓存
    # ─────────────────────────────────────────
    def _load_cache(self):
        if self.cache_file.exists():
            try:
                return json.loads(self.cache_file.read_text(encoding='utf-8'))
            except (ValueError, OSError):
                pass
        return {}

    def _save_cache(self):
        keys = list(self._cache.keys())[-1000:]
        trimmed = {k: self._cache[k] for k in keys}
        try:
            self.cache_file.write_text(
                json.dumps(trimmed, ensure_ascii=False), encoding='utf-8')
        except OSError:
            pass

    @staticmethod
    def _cache_key(text):
        return hashlib.md5(text.strip().encode('utf-8')).hexdigest()[:16]

    def _cache_lookup(self, text):
        entry = self._cache.get(self._cache_key(text))
        if entry and time.time() - entry.get('ts', 0) < CACHE_TTL:
            return entry['result']
        return None

    def _cache_store(self, text, result):
        self._cache[self._cache_key(text)] = {'ts': time.time(), 'result': result}
        self._save_cache()

    # ─────────────────────────────────────────
    # 规则匹配（零 Token）
    # ─────────────────────────────────────────
    def _rule_match(self, text):
        text_lower = text.lower()
        best, best_score = None, 0.0
        for rule in self.rules:
            score = 0.0
            kw = rule.get('keywords', [])
            matched_keywords = []
            for k in kw:
                if k.lower() in text_lower:
                    score += 1.0
                    matched_keywords.append(k)
            for c in rule.get('context_keywords', []):
                if c.lower() in text_lower:
                    score += 0.5
            if rule.get('regex') and re.search(rule['regex'], text):
                score += 1.5
            if score > 0:
                # shortcut 规则：只要匹配任意关键词就直接使用规则置信度
                if rule.get('shortcut') and matched_keywords:
                    confidence = rule.get('confidence', 0.9)
                else:
                    confidence = min(rule.get('confidence', 0.7),
                                     0.4 + score * 0.2)
                if confidence > best_score:
                    best_score = confidence
                    best = {
                        'intent': rule['intent'],
                        'skill': rule.get('skill'),
                        'confidence': round(confidence, 2),
                        'method': 'rule',
                        'shortcut': rule.get('shortcut', False),
                    }
        return best

    # ─────────────────────────────────────────
    # LLM 分类
    # ─────────────────────────────────────────
    def _llm_classify(self, text):
        if not self.llm or not self.config.llm_configured:
            return {'intent': 'unknown', 'skill': None,
                    'confidence': 0.0, 'method': 'fallback'}
        intents = sorted(set(r['intent'] for r in self.rules))
        system = (
            '你是意图分类器。将用户指令分类到以下意图之一：\n'
            '%s，或 "unknown"。\n'
            '输出严格 JSON：{"intent": "...", "confidence": 0.0-1.0}\n'
        ) % ', '.join(intents)
        try:
            result_str = self.llm.quick_prompt(
                system, '用户指令：%s' % text,
                skill='router', category='normal', json_mode=True,
                model='fast')
            data = json.loads(result_str)
            intent = data.get('intent', 'unknown')
            skill = None
            shortcut = False
            for r in self.rules:
                if r['intent'] == intent:
                    skill = r.get('skill')
                    shortcut = r.get('shortcut', False)
                    break
            return {
                'intent': intent,
                'skill': skill,
                'confidence': float(data.get('confidence', 0.5)),
                'method': 'llm',
                'shortcut': shortcut,
            }
        except (ValueError, KeyError, RuntimeError) as e:
            logger.error('LLM 意图分类失败: %s', e)
            return {'intent': 'unknown', 'skill': None,
                    'confidence': 0.0, 'method': 'error'}

    # ─────────────────────────────────────────
    # 主入口
    # ─────────────────────────────────────────
    def route(self, text):
        """返回 {intent, skill, confidence, method}。"""
        # 1. 规则匹配
        result = self._rule_match(text)
        if result and result['confidence'] >= 0.7:
            # 规则匹配成功 → 清除可能的旧缓存（避免旧缓存覆盖新规则）
            self._cache.pop(self._cache_key(text), None)
            logger.info('路由(规则): intent=%s conf=%s shortcut=%s',
                        result['intent'], result['confidence'],
                        result.get('shortcut', False))
            return result
        # 2. 缓存
        cached = self._cache_lookup(text)
        if cached:
            logger.info('路由(缓存): intent=%s', cached['intent'])
            return cached
        # 3. LLM 分类
        result = self._llm_classify(text)
        if result['confidence'] >= 0.5:
            self._cache_store(text, result)
            logger.info('路由(LLM): intent=%s conf=%s',
                        result['intent'], result['confidence'])
            return result
        # 4. Fallback
        logger.info('路由失败，无法识别意图: %s', text[:80])
        return {'intent': 'unknown', 'skill': None,
                'confidence': 0.0, 'method': 'fallback'}

    def list_intents(self):
        return sorted(set(r['intent'] for r in self.rules))
